        "vignetteName":  null,
        "vignetteStem":  "",
        "question":  "Normal-pressure hydrocephalus presents as the triad of:",
        "choices":  [
                        "Dementia, parkinsonism, and visual hallucinations",
                        "Dementia, ophthalmoplegia, and ataxia",
                        "Dementia, incontinence, and gait disturbance",
                        "Chorea, irritability, and obsessive-compulsive traits",
                        "Dementia, axial rigidity, and vertical ophthalmoplegia"
                    ],
        "choiceLetters":  [
                              "A",
                              "B",
                              "C",
                              "D",
                              "E"
                          ],
