        "vignetteName":  null,
        "vignetteStem":  "",
        "question":  "In normal young adults, what percentage of total sleep time is spent in REM sleep?",
        "choices":  [
                        "5%",
                        "0%",
                        "20%",
                        "25%",
                        "35%"
                    ],
